import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { placeBetHandler } from "../handlers/placeBetHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";
import type { PlaceBetRequest } from "../types/PlaceBetRequest";

type Data = Awaited<ReturnType<typeof placeBetHandler>>;
type Vars = { roundId: FactFoldRoundEntityType; req: PlaceBetRequest };

export function usePlaceBet(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => placeBetHandler(vars.roundId, vars.req),
    ...options,
  });
}
